ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* cur = &dummy;
    while (l1 && l2) {
        if (l1->val < l2->val) {
            cur->next = l1; l1 = l1->next;
        } else {
            cur->next = l2; l2 = l2->next;
        }
        cur = cur->next;
    }
    cur->next = l1 ? l1 : l2; // 接上剩余
    return dummy.next;
}
// 归并框架 | dummy省去头节点特殊处理 | 最后接剩余
